	err := row.Scan(
		&i.UserID,
		&i.Briefing,
		&i.Report,
		&i.Marketing,
		&i.MarketingOptInAt,
		&i.QuietEnabled,
		&i.QuietStart,
		&i.QuietEnd,
		&i.UpdatedAt,
	)
	return i, err
